mapper.select:
SELECT COUNT(*)
FROM pay_order
WHERE pay_order_status IN ('PAID','COMPLETED')
AND pay_order_pay_time >= #{start}
AND pay_order_pay_time < #{end}

SELECT COALESCE(SUM(pay_order_paid_amount), 0)
FROM pay_order
WHERE pay_order_status IN ('PAID','COMPLETED')
AND pay_order_pay_time >= #{start}
AND pay_order_pay_time < #{end}

SELECT COUNT(*)
FROM pay_order
WHERE pay_order_refund_amount > 0
AND pay_order_updated_at >= #{start}
AND pay_order_updated_at < #{end}

SELECT COALESCE(SUM(pay_order_refund_amount), 0)
FROM pay_order
WHERE pay_order_refund_amount > 0
AND pay_order_updated_at >= #{start}
AND pay_order_updated_at < #{end}

SELECT COUNT(*)
FROM pay_transaction_record

    AND pay_transaction_record_created_at >= #{start}
    AND pay_transaction_record_created_at < #{end}

SELECT COUNT(*)
FROM pay_notify_log

    AND pay_notify_log_received_at >= #{start}
    AND pay_notify_log_received_at < #{end}

SELECT COUNT(*)
FROM pay_notify_log
WHERE pay_notify_log_process_status = 'SUCCESS'
AND pay_notify_log_received_at >= #{start}
AND pay_notify_log_received_at < #{end}

SELECT COUNT(*)
FROM pay_notify_log
WHERE pay_notify_log_process_status = 'FAILED'
AND pay_notify_log_received_at >= #{start}
AND pay_notify_log_received_at < #{end}

SELECT COALESCE(AVG(
    TIMESTAMPDIFF(MICROSECOND, pay_notify_log_received_at, pay_notify_log_processed_at) / 1000
), 0)
FROM pay_notify_log
WHERE pay_notify_log_process_status IS NOT NULL AND pay_notify_log_processed_at IS NOT NULL
AND pay_notify_log_received_at >= #{start}
AND pay_notify_log_received_at < #{end}
